def load_checkpoint(db, task_id):
    doc = db.checkpoints.find_one({"task_id": task_id})
    if doc is None:
        return None
    return {
        "goal": doc["goal"],
        "plan": doc["plan"],
        "current_step": doc["current_step"],
        "results": doc.get("results", {}),
    }

