def run_task(db, task_id, task):
    for step in task["plan"]:
        if step["step"] < task["current_step"]:
            continue  # already done before the restart
        execute_step(step, task)
        task["current_step"] = step["step"] + 1
        save_checkpoint(db, task_id, task)
    print("task complete")

def get_status(db, task_id):
    doc = db.checkpoints.find_one({"task_id": task_id})
    if doc is None:
        return {"found": False}
    total_steps = len(doc["plan"])
    done_steps = doc["current_step"] - 1
    return {
        "found": True,
        "goal": doc["goal"],
        "progress": f"{done_steps} of {total_steps} steps done",
        "last_updated": doc["updated_at"],
    }

